// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/healthz", wrapper.GetHealth)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/currencies", wrapper.ListCurrencies)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/fx", wrapper.GetFxRate)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/groups", wrapper.CreateGroup)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/groups/{groupId}", wrapper.GetGroup)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/groups/{groupId}/members", wrapper.AddMember)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/v1/groups/{groupId}/members/{memberId}", wrapper.UpdateMember)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/groups/{groupId}/expenses", wrapper.CreateExpense)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/groups/{groupId}/settlements", wrapper.CreateSettlement)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/groups/{groupId}/transactions", wrapper.ListTransactions)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/groups/{groupId}/transactions/{transactionId}/reversal", wrapper.ReverseTransaction)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/groups/{groupId}/balances", wrapper.GetBalances)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/groups/{groupId}/members/{memberId}/payment-qr", wrapper.GetPaymentQr)

	return m
}

