// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetHealth Liveness and dependency check
	// (GET /healthz)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// ListCurrencies Supported currencies and their minor-unit exponents
	// (GET /v1/currencies)
	ListCurrencies(ctx context.Context, request ListCurrenciesRequestObject) (ListCurrenciesResponseObject, error)
	// GetFxRate Current exchange rate between two currencies
	// (GET /v1/fx)
	GetFxRate(ctx context.Context, request GetFxRateRequestObject) (GetFxRateResponseObject, error)
	// CreateGroup Create a group
	// (POST /v1/groups)
	CreateGroup(ctx context.Context, request CreateGroupRequestObject) (CreateGroupResponseObject, error)
	// GetGroup Get a group and its members
	// (GET /v1/groups/{groupId})
	GetGroup(ctx context.Context, request GetGroupRequestObject) (GetGroupResponseObject, error)
	// GetBalances Net balance per member and the transfers that settle the group
	// (GET /v1/groups/{groupId}/balances)
	GetBalances(ctx context.Context, request GetBalancesRequestObject) (GetBalancesResponseObject, error)
	// CreateExpense Record an expense
	// (POST /v1/groups/{groupId}/expenses)
	CreateExpense(ctx context.Context, request CreateExpenseRequestObject) (CreateExpenseResponseObject, error)
	// AddMember Add a member
	// (POST /v1/groups/{groupId}/members)
	AddMember(ctx context.Context, request AddMemberRequestObject) (AddMemberResponseObject, error)
	// UpdateMember Rename a member or set how they want to be paid
	// (PATCH /v1/groups/{groupId}/members/{memberId})
	UpdateMember(ctx context.Context, request UpdateMemberRequestObject) (UpdateMemberResponseObject, error)
	// GetPaymentQr Build a VietQR or PayNow payload that pays this member
	// (GET /v1/groups/{groupId}/members/{memberId}/payment-qr)
	GetPaymentQr(ctx context.Context, request GetPaymentQrRequestObject) (GetPaymentQrResponseObject, error)
	// CreateSettlement Record that one member paid another
	// (POST /v1/groups/{groupId}/settlements)
	CreateSettlement(ctx context.Context, request CreateSettlementRequestObject) (CreateSettlementResponseObject, error)
	// ListTransactions List ledger transactions, newest first
	// (GET /v1/groups/{groupId}/transactions)
	ListTransactions(ctx context.Context, request ListTransactionsRequestObject) (ListTransactionsResponseObject, error)
	// ReverseTransaction Cancel a transaction by posting its mirror image
	// (POST /v1/groups/{groupId}/transactions/{transactionId}/reversal)
	ReverseTransaction(ctx context.Context, request ReverseTransactionRequestObject) (ReverseTransactionResponseObject, error)
}

// StrictHandlerFunc and StrictMiddlewareFunc are type aliases rather than
// distinct named types, so middleware written against one generated package
// can be shared with every other generated package using the same framework.
type StrictHandlerFunc = func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc = func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

